{
  "root_cause": "The Awesomplete widget does not handle the Tab key when the suggestion list is open, allowing default tab navigation to move focus into the list items (which have tabindex=0) instead of moving to the next form field.",
  "repair_strategy": "Modify the input's keydown listener to close the suggestion list when Tab is pressed while the list is open, permitting the default tab action to shift focus to the next focusable element outside the widget.",
  "edits": [
    {
      "path": "awesomplete.js",
      "sha256": "b60dd8ec51ae96e979d58de3e9681449056b74a3d44031eb1121f325bc2e3af6",
      "before": "			"keydown": function(evt) {
				var c = evt.keyCode;

				// If the dropdown `ul` is in view, then act on keydown for the following keys:
				// Enter / Esc / Up / Down
				if(me.opened) {
					if (c === 13 && me.selected) { // Enter
						evt.preventDefault();
						me.select(undefined, undefined, evt);
					}
					else if (c === 9 && me.selected && me.tabSelect) {
						evt.preventDefault();
						me.select(undefined, undefined, evt);
					}
					else if (c === 27) { // Esc
						me.close({ reason: "esc" });
					}
					else if (c === 38 || c === 40) { // Down/Up arrow
						evt.preventDefault();
						me[c === 38? "previous" : "next"]();
					}
				}
			}
		},",
      "after": "			"keydown": function(evt) {
				var c = evt.keyCode;

				// If the dropdown `ul` is in view, then act on keydown for the following keys:
				// Enter / Esc / Up / Down
				if(me.opened) {
					if (c === 13 && me.selected) { // Enter
						evt.preventDefault();
						me.select(undefined, undefined, evt);
					}
					else if (c === 9) {
						me.close({ reason: "tab" });
					}
					else if (c === 27) { // Esc
						me.close({ reason: "esc" });
					}
					else if (c === 38 || c === 40) { // Down/Up arrow
						evt.preventDefault();
						me[c === 38? "previous" : "next"]();
					}
				}
			}
		},"
    }
  ],
  "expected_accessibility_effect": "Tab key will move focus from the city combobox to the dietary requirements input when suggestions are displayed, satisfying WCAG 2.1.1 keyboard accessibility and 2.4.3 focus order.",
  "functional_risks": [
    "Users who rely on selecting a suggestion with the Tab key when tabSelect is enabled may lose that functionality; however the default configuration has tabSelect false, so impact is minimal.",
    "Closing the list on Tab could interfere with assistive technology announcements if not properly managed, but the list is hidden before focus moves."
  ],
  "verification_requirements": [
    "After typing 'Ber' in the city field, pressing Tab must move focus to the dietary input (focus assertion).",
    "The suggestion list must have the hidden attribute after Tab press.",
    "The city field's value should remain unchanged (or reflect a selection if Enter used).",
    "Arrow key navigation and Enter selection must continue to work as per regression guards."
  ]
}

